create function pg_temp.fail_edit_event() returns trigger language plpgsql as $$ begin if new.event_type='edited' then raise exception 'forced event failure'; end if; return new; end $$;
create trigger test_edit_atomicity before insert on public.task_events for each row execute function pg_temp.fail_edit_event();
set local role authenticated; select set_config('request.jwt.claim.sub','25100000-0000-4000-8000-000000000004',true);
select throws_ok($$select public.edit_task('25100000-0000-4000-8000-000000000301','Should rollback','Should rollback',false)$$,'P0001','forced event failure','event and edit atomic');
select ok((select title='Novo título' and description is null and is_private from public.tasks where id='25100000-0000-4000-8000-000000000301'),'failure restores all fields');
reset role;
select is((select count(*) from public.task_events where task_id='25100000-0000-4000-8000-000000000301' and event_type='edited'),5::bigint,'no duplicate events from no-ops or failures');
select ok((select count(*)=1 from public.task_events where task_id='25100000-0000-4000-8000-000000000301' and details->'changes' = '{"is_private":{"before":false,"after":true}}'::jsonb),'privacy-only event lists only changed field');
